import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# Kernel 1: compute L2 norm per row.
compute_l2_norms_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void compute_l2_norms(const float* input, float* norms, int rows, int dim) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < rows) {
        const float* row_ptr = input + row * dim;
        float sum = 0.0f;
        for (int i = 0; i < dim; ++i) {
            sum += row_ptr[i];
        }
        norms[row] = sqrt(sum);
    }
}
"""

# Kernel 2: divide each element by the norm of its row.
divide_by_norm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void divide_by_norms(const float* input, const float* norms, float* output, int rows, int dim) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < rows * dim) {
        int row = idx / dim;
        int col = idx % dim;
        output[idx] = input[idx] / norms[row];
    }
}
"""

# Load the kernels
compute_l2_norms_kernel = load_inline(
    name="compute_l2_norms",
    cpp_sources=[],
    cuda_sources=compute_l2_norms_source,
    functions=[],
)

divide_by_norm_kernel = load_inline(
    name="divide_by_norm",
    cpp_sources=[],
    cuda_sources=divide_by_norm_source,
    functions=[],
)

# Fused L2 normalization operator (C++ function)
l2norm_cuda_source = """
torch::Tensor l2norm_cuda(torch::Tensor x) {
    auto size = x.numel();
    int rows = size / x.size(1);
    int dim = x.size(1);

    float* input_ptr = x.data_ptr<float>();
    float* norms;
    float* output_ptr;

    cudaMalloc(&norms, rows * sizeof(float));
    cudaMalloc(&output_ptr, size * sizeof(float));

    // Compute row-wise L2 norms
    const int block_size = 256;
    const int num_blocks_norms = (rows + block_size - 1) / block_size;
    compute_l2_norms<<<num_blocks_norms, block_size>>>(input_ptr, norms, rows, dim);
    cudaDeviceSynchronize();

    // Divide each element by its row's norm
    const int num_blocks_div = (size + block_size - 1) / block_size;
    divide_by_norm<<<num_blocks_div, block_size>>>(input_ptr, norms, output_ptr, rows, dim);
    cudaDeviceSynchronize();

    cudaFree(norms);
    cudaFree(output_ptr);

    // Build result tensor
    auto out = torch::empty(x.shape(), dtype=torch.float32, device=x.device);
    out.copy_from_blob(output_ptr);
    return out;
}
"""

l2norm_cuda = load_inline(
    name="l2norm_cuda",
    cpp_sources=[],
    cuda_sources=l2norm_cuda_source,
    functions=["l2norm_cuda"],
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.l2norm_cuda = l2norm_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.l2norm_cuda(x)


